(function() {
    'use strict';

    class PlatformBuilderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Platform Business Builder';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    phase: 'Launch',
                    description: '<b>Months 1\u20134: The Chicken-and-Egg Problem</b><br><br>Conecta has 35 pre-committed providers and 280 registered (but inactive) buyers in Bogot\u00e1. Zero transactions have occurred. Your seed funding gives you 18 months of runway at $95,000/month burn.<br><br>Key challenge: Which side do you prioritize? Providers need to see transactions within 60 days or they will leave. Buyers need enough provider choice to find a match.<br><br>Set your BD focus, initial take rate, and decide how much to invest in trust and quality systems.',
                    showExpansion: false,
                    showCompetitive: false
                },
                {
                    phase: 'Early Growth',
                    description: '<b>Months 5\u20138: Liquidity and Match Quality</b><br><br>You now have real transaction data. The match success rate \u2014 the percentage of buyer requests resulting in completed transactions \u2014 is the single most predictive metric of platform health.<br><br>A platform with 1,000 registered providers but a 15% match rate is sicker than one with 200 providers and a 45% match rate.<br><br>Focus on improving matching algorithms, consider standardizing service categories, and decide whether to enforce response time standards for providers.',
                    showExpansion: false,
                    showCompetitive: false
                },
                {
                    phase: 'Scaling',
                    description: '<b>Months 9\u201312: Take Rate Optimization and Quality</b><br><br>Growth vs. monetization tension emerges. Your top 3 providers (22% of GMV) are requesting lower take rates. A buyer complaint about failed delivery went viral.<br><br>Consider: Should you introduce premium provider tiers? Adjust take rates? Launch buyer subscriptions?<br><br>Warning: A 3\u20135 percentage point take rate increase typically triggers 15\u201325% short-term provider churn.',
                    showExpansion: false,
                    showCompetitive: false
                },
                {
                    phase: 'Expansion',
                    description: '<b>Months 13\u201316: Geography vs. Vertical vs. Enterprise</b><br><br>Conecta has a working platform in Bogot\u00e1. A $2M Series A extension is available. A competitor in Mexico City just raised $10M and plans to enter Colombia in 6 months.<br><br>Choose your expansion path:<br>\u2022 <b>Geographic:</b> Launch in Medell\u00edn (rebuild local density from scratch)<br>\u2022 <b>Vertical:</b> Build specialized Conecta Legal product<br>\u2022 <b>Enterprise:</b> Develop B2B procurement for 500+ employee companies<br>\u2022 Or stay focused on deepening Bogot\u00e1',
                    showExpansion: true,
                    showCompetitive: false
                },
                {
                    phase: 'Competition',
                    description: '<b>Months 17\u201320: Competitive Response and Moat-Building</b><br><br>ProServicios has launched in Bogot\u00e1 with zero take rate for 6 months, a $200K marketing campaign, and provider signing bonuses. Two of your top-10 providers are now multi-homing.<br><br>A US-based marketplace with 2M provider profiles announces LATAM expansion.<br><br>How do you defend? Match pricing? Lock in providers? Deepen buyer integrations? Accelerate certification programs?',
                    showExpansion: true,
                    showCompetitive: true
                },
                {
                    phase: 'Consolidation',
                    description: '<b>Months 21\u201324: Series B Readiness</b><br><br>ProServicios is running out of runway. MercadoLibre ecosystem fund offers a $5M Series B \u2014 but requires white-labeling your technology across 6 LATAM markets.<br><br>Focus on unit economics: contribution margin per transaction, LTV:CAC ratio, and path to profitability. Your decisions this round determine whether Conecta is fundable, acquirable, or in structural distress.<br><br>PHI above 70 = fundable. Above 85 = acquisition target. Below 50 = structural distress.',
                    showExpansion: true,
                    showCompetitive: true
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 4000000,
                    activeProviders: 35,
                    activeBuyers: 0,
                    registeredBuyers: 280,
                    monthlyGMV: 0,
                    matchRate: 0,
                    npsBuyer: 50,
                    npsProvider: 50,
                    phi: 0,
                    totalRevenue: 0,
                    avgTransactionValue: 2500,
                    providerChurnRate: 5,
                    buyerRepeatRate: 0,
                    monthsRunway: 18,
                    cumulativeGMV: 0,
                    gmvHistory: [],
                    phiHistory: [],
                    matchRateHistory: [],
                    revenueHistory: [],
                    providerHistory: [],
                    buyerHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    bdProviderPct: 50,
                    takeRate: 10,
                    marketingBudget: 10000,
                    qualityInvestment: 5000,
                    expansionStrategy: 0,
                    competitiveResponse: 0
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): undo restores state but never re-invokes the view,
                // leaving a stale briefing/phase and wrong decision-group visibility.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var bdInput = document.getElementById('bdProviderInput');
            if (bdInput) decisions.bdProviderPct = parseFloat(bdInput.value);

            var trInput = document.getElementById('takeRateInput');
            if (trInput) decisions.takeRate = parseFloat(trInput.value);

            var mkInput = document.getElementById('marketingInput');
            if (mkInput) decisions.marketingBudget = parseFloat(mkInput.value);

            var qInput = document.getElementById('qualityInput');
            if (qInput) decisions.qualityInvestment = parseFloat(qInput.value);

            var expInput = document.getElementById('expansionInput');
            if (expInput) decisions.expansionStrategy = parseInt(expInput.value);

            var compInput = document.getElementById('competitiveInput');
            if (compInput) decisions.competitiveResponse = parseInt(compInput.value);

            if (isNaN(decisions.bdProviderPct) || decisions.bdProviderPct < 0 || decisions.bdProviderPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('bd_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.takeRate) || decisions.takeRate < 0 || decisions.takeRate > 25) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('take_rate_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.marketingBudget) || decisions.marketingBudget < 0 || decisions.marketingBudget > 80000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.qualityInvestment) || decisions.qualityInvestment < 0 || decisions.qualityInvestment > 50000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('quality_warning'), 'warning'
                );
                return false;
            }

            var totalMonthlySpend = 95000 + decisions.marketingBudget + decisions.qualityInvestment;
            var roundSpend = totalMonthlySpend * 4;
            // FIX(v1.1.0): validateDecisions has no `state` param — referencing
            // `state` here threw a ReferenceError on every submit, blocking the
            // entire simulation. Read the live state instead. (Non-blocking warning.)
            if (window.mySimulation && roundSpend > window.mySimulation.state.domainState.cash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('cash_warning'), 'warning'
                );
            }

            // FIX(v1.1.0): removed a redundant _updateBriefing() here; the next
            // round is rendered by calculateResults. (Also avoids re-toggling the
            // decision groups on the deep-cloned competition-preview path.)
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var providerBDEffort = d.bdProviderPct / 100;
            var buyerBDEffort = 1 - providerBDEffort;

            var baseNewProviders = Math.round(providerBDEffort * 35);
            var marketingProviderBoost = Math.round(d.marketingBudget / 12000 * 5);
            var takeRatePenalty = d.takeRate > 15 ? Math.round((d.takeRate - 15) * 3) : 0;
            var qualityProviderBoost = Math.round(d.qualityInvestment / 10000 * 4);
            var newProviders = Math.max(0, baseNewProviders + marketingProviderBoost + qualityProviderBoost - takeRatePenalty);

            var providerChurnPct = 5;
            if (d.takeRate > 15) providerChurnPct += (d.takeRate - 15) * 2;
            if (ds.matchRate < 25 && period > 1) providerChurnPct += 5;
            if (d.competitiveResponse === 0 && period >= 5) providerChurnPct += 8;
            if (d.competitiveResponse === 1 && period >= 5) providerChurnPct -= 3;
            providerChurnPct = Math.max(2, Math.min(providerChurnPct, 35));
            var churningProviders = Math.round(ds.activeProviders * providerChurnPct / 100);
            var activeProviders = Math.max(10, ds.activeProviders + newProviders - churningProviders);

            if (d.expansionStrategy === 1 && period >= 4) {
                activeProviders += Math.round(15 * (period - 3));
            }
            if (d.expansionStrategy === 2 && period >= 4) {
                activeProviders += Math.round(8 * (period - 3));
            }

            var baseNewBuyers = Math.round(buyerBDEffort * 90);
            var marketingBuyerBoost = Math.round(d.marketingBudget / 8000 * 25);
            var matchRateBoost = ds.matchRate > 30 ? Math.round((ds.matchRate - 30) * 1.5) : 0;
            var newBuyers = Math.max(0, baseNewBuyers + marketingBuyerBoost + matchRateBoost);

            var buyerChurnPct = 8;
            if (ds.matchRate < 30 && period > 1) buyerChurnPct += 10;
            if (ds.matchRate > 50) buyerChurnPct -= 3;
            buyerChurnPct = Math.max(3, Math.min(buyerChurnPct, 30));
            var churningBuyers = Math.round(ds.activeBuyers * buyerChurnPct / 100);
            var activeBuyers = Math.max(0, ds.activeBuyers + newBuyers - churningBuyers);

            if (d.expansionStrategy === 1 && period >= 4) {
                activeBuyers += Math.round(60 * (period - 3));
            }
            if (d.expansionStrategy === 3 && period >= 4) {
                activeBuyers += Math.round(25 * (period - 3));
            }

            var providerDensity = activeBuyers > 0 ? Math.min(activeProviders / (activeBuyers * 0.08), 1.5) : 0;
            var baseMatchRate = providerDensity * 30;
            var qualityMatchBoost = d.qualityInvestment / 8000 * 12;
            var matchRate = Math.min(75, Math.max(5, baseMatchRate + qualityMatchBoost));
            if (period === 1 && activeBuyers < 50) matchRate = Math.min(matchRate, 35);
            if (d.expansionStrategy === 2 && period >= 4) matchRate += 5;
            matchRate = Math.round(matchRate * 10) / 10;

            var successfulMatches = Math.round(activeBuyers * matchRate / 100);
            var avgTxnValue = 2500 + (d.qualityInvestment / 5000 * 500) + (period * 200);
            if (d.expansionStrategy === 3 && period >= 4) avgTxnValue += 2000;
            var monthlyGMV = successfulMatches * avgTxnValue;

            var monthlyRevenue = monthlyGMV * d.takeRate / 100;
            if (d.competitiveResponse === 1 && period >= 5) monthlyRevenue = 0;

            var baseBurn = 95000;
            var totalMonthlyBurn = baseBurn + d.marketingBudget + d.qualityInvestment;
            if (d.expansionStrategy === 1 && period >= 4) totalMonthlyBurn += 40000;
            if (d.expansionStrategy === 2 && period >= 4) totalMonthlyBurn += 25000;
            if (d.expansionStrategy === 3 && period >= 4) totalMonthlyBurn += 35000;
            if (d.competitiveResponse === 2 && period >= 5) totalMonthlyBurn += 20000;
            if (d.competitiveResponse === 3 && period >= 5) totalMonthlyBurn += 15000;

            var roundRevenue = monthlyRevenue * 4;
            var roundCost = totalMonthlyBurn * 4;
            var roundProfit = roundRevenue - roundCost;
            var cash = ds.cash + roundProfit;

            if (period === 4) cash += 2000000;

            var monthsRunway = totalMonthlyBurn > monthlyRevenue ? cash / (totalMonthlyBurn - monthlyRevenue) : 36;
            monthsRunway = Math.max(0, Math.round(monthsRunway * 10) / 10);

            var buyerNPS = 50;
            buyerNPS += (matchRate - 30) * 0.8;
            buyerNPS += d.qualityInvestment / 5000 * 5;
            if (matchRate < 25) buyerNPS -= 15;
            buyerNPS = Math.round(Math.max(-10, Math.min(90, buyerNPS)));

            var providerNPS = 50;
            providerNPS -= (d.takeRate - 10) * 2;
            providerNPS += (matchRate - 30) * 0.5;
            providerNPS += d.qualityInvestment / 10000 * 5;
            if (d.competitiveResponse === 1 && period >= 5) providerNPS += 10;
            if (providerChurnPct > 15) providerNPS -= 10;
            providerNPS = Math.round(Math.max(-10, Math.min(90, providerNPS)));

            var gmvGrowth = ds.monthlyGMV > 0 ? (monthlyGMV - ds.monthlyGMV) / ds.monthlyGMV * 100 : (monthlyGMV > 0 ? 100 : 0);
            var gmvScore = Math.min(20, Math.max(0, gmvGrowth * 0.5));
            var matchScore = Math.min(25, Math.max(0, matchRate / 65 * 25));
            var npsAvg = (buyerNPS + providerNPS) / 2;
            var npsScore = Math.min(25, Math.max(0, npsAvg / 70 * 25));
            var liquidityRatio = activeBuyers > 0 ? activeProviders / activeBuyers : 0;
            var optimalRatio = 0.15;
            var ratioDeviation = Math.abs(liquidityRatio - optimalRatio);
            var ratioScore = Math.min(15, Math.max(0, 15 - ratioDeviation * 50));
            var runwayScore = Math.min(15, Math.max(0, monthsRunway / 18 * 15));
            var phi = Math.round(gmvScore + matchScore + npsScore + ratioScore + runwayScore);
            phi = Math.max(0, Math.min(100, phi));

            ds.cash = Math.round(cash);
            ds.activeProviders = activeProviders;
            ds.activeBuyers = activeBuyers;
            ds.monthlyGMV = Math.round(monthlyGMV);
            ds.matchRate = matchRate;
            ds.npsBuyer = buyerNPS;
            ds.npsProvider = providerNPS;
            ds.phi = phi;
            ds.totalRevenue += roundRevenue;
            ds.avgTransactionValue = Math.round(avgTxnValue);
            ds.providerChurnRate = Math.round(providerChurnPct * 10) / 10;
            ds.buyerRepeatRate = Math.round(Math.min(70, matchRate * 0.9) * 10) / 10;
            ds.monthsRunway = monthsRunway;
            ds.cumulativeGMV += monthlyGMV * 4;

            ds.gmvHistory.push(Math.round(monthlyGMV));
            ds.phiHistory.push(phi);
            ds.matchRateHistory.push(matchRate);
            ds.revenueHistory.push(Math.round(monthlyRevenue));
            ds.providerHistory.push(activeProviders);
            ds.buyerHistory.push(activeBuyers);

            // FIX(v1.1.0): advance synchronously to the next round. The previous
            // setTimeout closure read state.currentPeriod AFTER the framework had
            // incremented it, so the briefing, phase label, and — most damaging —
            // the expansion/competitive decision-group visibility jumped to round
            // N+2 (e.g. Round 4 wrongly showed Round 5's groups). Guard on state
            // identity so the deep-cloned competition preview never mutates the DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                monthlyGMV: Math.round(monthlyGMV),
                monthlyRevenue: Math.round(monthlyRevenue),
                roundProfit: Math.round(roundProfit),
                activeProviders: activeProviders,
                activeBuyers: activeBuyers,
                matchRate: matchRate,
                phi: phi,
                npsBuyer: buyerNPS,
                npsProvider: providerNPS,
                cash: Math.round(cash),
                newProviders: newProviders,
                newBuyers: newBuyers,
                providerChurn: providerChurnPct,
                monthsRunway: monthsRunway
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('gmvDisplay', 'domainState.monthlyGMV',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('matchRateDisplay', 'domainState.matchRate',
                (v) => v + '%');
            uiManager.bind('providersDisplay', 'domainState.activeProviders');
            uiManager.bind('buyersDisplay', 'domainState.activeBuyers');
            uiManager.bind('phiDisplay', 'domainState.phi',
                (v) => v + '/100');
            uiManager.bind('npsBuyerDisplay', 'domainState.npsBuyer');
            uiManager.bind('npsProviderDisplay', 'domainState.npsProvider');
        }

        getChartConfig() {
            return {
                gmvChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Monthly GMV ($)',
                            data: [],
                            backgroundColor: 'rgba(52,152,219,0.6)',
                            borderColor: '#3498db',
                            borderWidth: 2
                        }, {
                            label: 'Monthly Revenue ($)',
                            data: [],
                            backgroundColor: 'rgba(39,174,96,0.6)',
                            borderColor: '#27ae60',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'GMV and Revenue by Round' } },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                healthChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Platform Health Index (PHI)',
                            data: [],
                            borderColor: '#8e44ad',
                            backgroundColor: 'rgba(142,68,173,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Match Rate (%)',
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Platform Health Over Time' } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.gmvHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                gmvChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.gmvHistory },
                        { data: state.domainState.revenueHistory }
                    ]
                },
                healthChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.phiHistory },
                        { data: state.domainState.matchRateHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var finalState = history[history.length - 1];
            var phi = finalState.results ? finalState.results.phi : 0;
            var totalGMV = history.reduce(function(s, r) { return s + (r.results ? r.results.monthlyGMV * 4 : 0); }, 0);
            var avgMatchRate = history.reduce(function(s, r) { return s + (r.results ? r.results.matchRate : 0); }, 0) / history.length;
            var finalCash = finalState.results ? finalState.results.cash : 0;

            var performance = 'Structural Distress';
            if (phi >= 50) performance = 'Viable but Vulnerable';
            if (phi >= 70) performance = 'Fundable Platform';
            if (phi >= 85) performance = 'Acquisition Target';

            var insights = [];
            if (avgMatchRate < 30) {
                insights.push('Match rate remained below 30% on average. Liquidity was the primary bottleneck \u2014 consider investing more in quality and matching systems.');
            }
            if (avgMatchRate >= 45) {
                insights.push('Strong match rate achieved. The marketplace delivered consistent value to both sides.');
            }
            if (finalCash < 500000) {
                insights.push('Cash reserves are critically low. Runway management needed improvement.');
            }
            if (phi >= 70) {
                insights.push('Platform Health Index indicates a fundable business. Network effects are building defensibility.');
            }
            if (phi < 50) {
                insights.push('Platform is in structural distress. Review whether early side-prioritization and take rate decisions created compounding problems.');
            }

            return {
                phi: phi,
                totalGMV: totalGMV,
                avgMatchRate: Math.round(avgMatchRate * 10) / 10,
                finalCash: finalCash,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.matchRate < 20) return window.mySimulation.t('hint_low_match');
            if (results.providerChurn > 20) return window.mySimulation.t('hint_high_churn');
            if (results.monthsRunway < 6) return window.mySimulation.t('hint_low_runway');
            if (results.phi >= 70) return window.mySimulation.t('hint_strong_phi');
            if (results.monthlyGMV === 0 && state.currentPeriod > 1) return window.mySimulation.t('hint_no_gmv');
            return null;
        }

